import{_ as i,o as s,c as t,a2 as e}from"./chunks/framework.DNkSpPuX.js";const k=JSON.parse('{"title":"项目介绍","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":1794045200000}'),l={name:"guide/introduction.md"};function n(p,a,d,h,r,o){return s(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="项目介绍" tabindex="-1">项目介绍 <a class="header-anchor" href="#项目介绍" aria-label="Permalink to &quot;项目介绍&quot;">​</a></h1><p>Vue-Bag-Admin 是一套面向 Vue 3 中后台项目的插件化开发框架。它把后台应用拆成稳定的宿主和可独立维护的业务插件，让项目可以先快速启动，再随着业务增长逐步拆分。</p><p>如果你第一次接触这个项目，先记住一句话：</p><blockquote><p>宿主负责把应用跑起来，插件负责把业务装进去。</p></blockquote><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>普通后台项目通常从一个 <code>src/views</code> 开始。页面少时很直接，业务增加后容易遇到这些问题：</p><ul><li>路由、菜单和权限散落在不同文件中，新增模块要改很多地方。</li><li>商品、订单、系统设置等业务相互引用，很难独立复用。</li><li>多个后台项目需要相同能力时，只能复制代码。</li><li>公共布局、请求和组件不断被业务代码侵入，升级成本越来越高。</li></ul><p>Vue-Bag-Admin 通过宿主与插件分层，把这些职责重新归位：</p><table tabindex="0"><thead><tr><th>层级</th><th>负责什么</th></tr></thead><tbody><tr><td>宿主</td><td>应用初始化、布局、路由守卫、登录态、菜单容器和插件装载</td></tr><tr><td>插件</td><td>业务页面、路由、菜单、多语言和插件初始化</td></tr><tr><td>协议</td><td>统一插件、路由 Meta、菜单、权限、表单 Schema 等数据结构</td></tr><tr><td>基础能力</td><td>HTTP、Fetch、WebSocket、表格、表单和字典组件</td></tr></tbody></table><h2 id="两种使用方式" tabindex="-1">两种使用方式 <a class="header-anchor" href="#两种使用方式" aria-label="Permalink to &quot;两种使用方式&quot;">​</a></h2><h3 id="创建自己的后台项目" tabindex="-1">创建自己的后台项目 <a class="header-anchor" href="#创建自己的后台项目" aria-label="Permalink to &quot;创建自己的后台项目&quot;">​</a></h3><p>这是大多数使用者应该选择的方式。通过脚手架创建一个独立项目：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dlx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @melt-js/libs-bag-create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-admin</span></span></code></pre></div><p>生成后的项目只依赖统一入口包 <code>@melt-js/libs-bag-entry</code>，不需要复制整个 Monorepo。业务可以先写成本地插件，需要跨项目复用时再发布成独立 npm 包。</p><h3 id="开发框架仓库" tabindex="-1">开发框架仓库 <a class="header-anchor" href="#开发框架仓库" aria-label="Permalink to &quot;开发框架仓库&quot;">​</a></h3><p>如果你要修改框架、官方插件或参考后端，可以直接开发当前 Monorepo：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tpl-vue3-admin-naive-bag       示例宿主</span></span>
<span class="line"><span>docs-bag                       文档站</span></span>
<span class="line"><span>service-bag-strapi             Strapi 参考后端</span></span>
<span class="line"><span>libs-*/comps-*                 框架包、脚手架和官方插件</span></span></code></pre></div><p>这条路线面向框架维护者，不是创建业务项目的前置条件。</p><h2 id="核心运行模型" tabindex="-1">核心运行模型 <a class="header-anchor" href="#核心运行模型" aria-label="Permalink to &quot;核心运行模型&quot;">​</a></h2><p>应用启动时主要发生四件事：</p><ol><li>宿主创建 Vue、Pinia、i18n 和 Router 实例。</li><li>宿主注入认证和请求配置。</li><li><code>bootstrapPlugins()</code> 收集已启用插件，注册路由、菜单和语言包。</li><li><code>HostApp</code> 根据当前路由渲染布局、导航和业务页面。</li></ol><p>插件不是一个特殊的 Vue 应用。它本质上是一个符合 <code>AdminPlugin</code> 协议的对象：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { AdminPlugin } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@melt-js/libs-bag-entry&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> reportPlugin</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> AdminPlugin</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  id: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;report-plugin&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  name: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;报表插件&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  version: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;1.0.0&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  routes: [],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  menus: []</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> default</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> reportPlugin</span></span></code></pre></div><p>因此，本地业务模块和发布到 npm 的插件使用同一套接入方式。</p><h2 id="包的职责" tabindex="-1">包的职责 <a class="header-anchor" href="#包的职责" aria-label="Permalink to &quot;包的职责&quot;">​</a></h2><p>业务项目通常只需要直接安装 <code>@melt-js/libs-bag-entry</code>。它统一导出了下面几层公开能力：</p><table tabindex="0"><thead><tr><th>包</th><th>定位</th></tr></thead><tbody><tr><td><code>@melt-js/libs-bag-core</code></td><td>插件、路由、菜单、权限、字典和表单 Schema 协议</td></tr><tr><td><code>@melt-js/libs-bag-request</code></td><td>HTTP、Fetch、WebSocket 和请求状态控制</td></tr><tr><td><code>@melt-js/libs-bag-ui</code></td><td><code>PmProTable</code>、<code>PmProForm</code>、<code>PmSchemaForm</code> 等组件</td></tr><tr><td><code>@melt-js/libs-bag-host</code></td><td>宿主布局、路由守卫、权限和插件引导</td></tr><tr><td><code>@melt-js/libs-bag-entry</code></td><td>面向业务项目的统一入口</td></tr><tr><td><code>@melt-js/libs-bag-create</code></td><td>创建独立宿主项目的脚手架</td></tr><tr><td><code>@melt-js/comps-bag-*</code></td><td>可选的独立业务插件</td></tr></tbody></table><p>除非你在维护底层分包，否则业务代码建议统一从 <code>@melt-js/libs-bag-entry</code> 导入，避免项目中出现多套运行时入口。</p><h2 id="技术栈与边界" tabindex="-1">技术栈与边界 <a class="header-anchor" href="#技术栈与边界" aria-label="Permalink to &quot;技术栈与边界&quot;">​</a></h2><p>前端运行时基于 Vue 3.5、Vite 6、TypeScript、Vue Router 4、Pinia、Vue I18n、Naive UI 和 Tailwind CSS。</p><p>仓库同时提供 Strapi 5 与 MySQL 参考后端，但前端并不绑定 Strapi。只要认证接口能够返回 token、用户角色和权限点，就可以接入 Java、Go、PHP 或其他后端。</p><p>Vue-Bag-Admin 更适合：</p><ul><li>有多个业务域、需要长期演进的中后台。</li><li>希望在多个后台项目之间复用业务模块。</li><li>想统一路由、菜单、权限和页面搭建方式的团队。</li></ul><p>如果项目只有少量固定页面，并且不会复用或扩展，直接使用 Vue Router 和组件库可能更简单。</p><h2 id="推荐阅读顺序" tabindex="-1">推荐阅读顺序 <a class="header-anchor" href="#推荐阅读顺序" aria-label="Permalink to &quot;推荐阅读顺序&quot;">​</a></h2><p>第一次使用时，按这条链路阅读即可：</p><ol><li><a href="./getting-started.html">快速上手</a></li><li><a href="./create-project.html">创建项目</a></li><li><a href="./host/bootstrap.html">初始化宿主</a></li><li><a href="./host/routing-and-menu.html">路由与菜单</a></li><li><a href="./host/auth-and-permissions.html">登录与权限</a></li><li><a href="./request-and-components.html">请求与组件</a></li></ol><p>完成主线后，可以按目标继续阅读：</p><ul><li>安装现有能力：<a href="./official-plugins/">官方插件</a></li><li>开发业务扩展：<a href="./plugins/create-plugin.html">插件开发</a></li></ul>`,39)])])}const u=i(l,[["render",n]]);export{k as __pageData,u as default};
